import React, { Component } from "react";
import WeatherResults from "../WeatherResults/WeatherResults";
import "./WeatherDashboard.css"; // Import the CSS file
import  UseWeather  from "../hooks/UseWeather";
import WeatherForecast from "../WeatherForecast/WeatherForecast";
import "../styles/global.css";
import "../styles/variables.scss";
import "../styles/utility.scss";
// import FutureWeatherData from "../FutureWeatherData/FutureWeatherData";

class UserInput extends Component {
  render() {
    const { input, onSearch, onChange, onTabChange, OnToggleChange, showFahren } = this.props;
    return (
      <>
        <div>
          <label className="toggle-switch">
            <input onClick={() => OnToggleChange(!showFahren)} type="checkbox" />
            <span className="slider"></span>
          </label>
        </div>
        <div>
          <div className="tabs flex flex-row-reverse gap-lg">
            <div className="tab" onClick={() => onTabChange('current')}>Today</div>
            <div className="tab" onClick={() => onTabChange('future')}>14-Day Forecast</div>
          </div>
        </div>
        <div className="search-container">
          <input
            className="border-radius-xxl"
            type="text"
            value={input}
            onChange={onChange} // Use the correct prop name
            placeholder="Enter city..."
          />
          <button onClick={onSearch}>Search</button>
        </div>
      </>
    );
  }
}

class WeatherDashboard extends Component {
  constructor() {
      super();
      this.state = {
          input: "",
          activeTab: "current",
          showFahren: true,
          results: null,
          hourlyResults: null,
          loading: false,
          error: null,
      };
      this.UseWeather = new UseWeather();
  }

  // Fetch weather data
  fetchWeather = (input) => {
      this.setState({ loading: true, error: null });
      const { fetchWeather } = UseWeather(); // Assuming fetchWeather is a function returned from UseWeather 146

      fetchWeather(input)
          .then(data => {
              this.setState({
                  results: data.results,
                  hourlyResults: data.hourlyResults,
                  loading: false,
              });
          })
          .catch(err => {
              this.setState({ error: err.message, loading: false });
          });
  };

  handleSearch = async (e) => {
    e.preventDefault();
    const weatherData = await fetchWeather(this.state.input);
    // this.UseWeather.fetchWeather(this.state.input).then(() => {
        this.setState({
            results: weatherData.results,
            hourlyResults: weatherData.hourlyResults,
            loading: weatherData.loading,
            error: weatherData.error,
        });
    // });
  };

  handleFutureWeatherData = (tab) => {
      this.setState({ activeTab: tab });
  }

  handleToggleChange = (value) => {
      this.setState({ showFahren: value });
  }

  handleInputChange = (event) => {
      this.setState({ input: event.target.value });
  };

  render() {
      const { input, activeTab, showFahren, results, hourlyResults, loading, error } = this.state;

      return (
          <div className="weather-app">
              <UserInput
                  input={input}
                  onChange={this.handleInputChange}
                  onSearch={this.handleSearch}
                  onTabChange={this.handleFutureWeatherData}
                  OnToggleChange={this.handleToggleChange}
                  showFahren={showFahren}
              />
              <div>
                  {loading && <p>LOADING ...</p>}
                  {error && <p>{error}</p>}
                  {!results && !loading && !error && <p>There are no results</p>}
              </div>
              {results && (
                  <div>
                      {activeTab === 'current' ? (
                          <WeatherResults results={results} hourlyResults={hourlyResults} showFahren={showFahren} />
                      ) : null}
                      {activeTab === 'future' ? (
                          <WeatherForecast results={results} hourlyResults={hourlyResults} showFahren={showFahren} />
                      ) : null}
                  </div>
              )}
          </div>
      );
  }
}

export default WeatherDashboard;
